class World35Baseline(unittest.TestCase):
 def test_original_world_state_consumers(self):
  source=fixture.HARNESS[:fixture.HARNESS.index('int main(')]+BASELINE_MAIN
  source=re.sub(r'namespace GameFileReader \{\nTextReadResult[\s\S]*?\n\}\n\}', '',source,count=1)
  with tempfile.TemporaryDirectory(prefix='api300-world-red-')as d:
   binary=build_lua_harness(source_root=fixture.SOURCE,workdir=Path(d),harness_source=source)
   result=subprocess.run([str(binary)],capture_output=True,text=True);self.assertEqual(result.returncode,0,result.stdout+result.stderr)

